SELECT id, product_id, quantity, DENSE_RANK() OVER (PARTITION BY product_id, store_id ORDER BY quantity DESC) AS quantity_dense_rank, AVG(quantity) OVER (PARTITION BY YEAR(last_restock), product_id ORDER BY last_restock ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS quantity_avg_3, LEAD(quantity, 1) OVER (ORDER BY last_restock ASC, id ASC) AS next_quantity FROM inventory WHERE store_id IN (3, 6);
